window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-99edd6fb5bc44f1d"]={"versions": [{"id": "FIG-99edd6fb5bc44f1d", "releases": ["R22-11", "R23-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt (M2-Ebene) mit Tagged-Value-Spezifikation.</li>\n<li><strong>Funktionale Einordnung & Zweck:</strong></li>\n<li>Das Diagramm stammt aus der AUTOSAR-Foundation-Spezifikation <em>TPS XML Schema Production Rules</em> (<code>AUTOSAR_FO_TPS_XMLSchemaProductionRules</code>, Kapitel 4 „Mapping of Classes“).</li>\n<li>Es demonstriert die normative Vorschrift zur Transformation von Metamodell-Klassen in W3C-XML-Schema-Definitionen (<code>.xsd</code>).</li>\n<li>Standardmäßig werden AUTOSAR-Metaklassen ausschließlich auf <code>xsd:complexType</code> abgebildet. Um ein Wurzelelement für ARXML-Dateien im XSD-Schema global instanziierbar zu machen, dient die UML-Tag-Spezifikation <code>xml.globalElement = true</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Entitäten & Metaklassen:</strong></li>\n<li><code>AUTOSAR</code>: Zentrale Metaklasse an der Spitze der AUTOSAR-Modellhierarchie (Container für <code>ARPackage</code>-Strukturen).</li>\n<li><strong>Stereotypen & Tags (Tagged Values):</strong></li>\n<li>Fachbereich/Compartment: <code>tags</code></li>\n<li><code>xml.globalElement = true</code>: Schalter-Tag für den XSD-Generator gemäß <code>TPS_XMLSPR_00003</code> und <code>TPS_XMLSPR_00005</code>.</li>\n<li><strong>Beziehungen & Kardinalitäten:</strong></li>\n<li>Im Diagramm isoliert als normatives Definitionsmuster dargestellt.</li>\n<li>Im vollständigen Metamodell aggregiert die Metaklasse <code>AUTOSAR</code> die Elemente vom Typ <code>ARPackage</code> (<code>0..*</code>).</li>\n<li>Durch das gesetzte Tag wird die Klasse im Ziel-Schema zu einem globalen Element deklariert:</li>\n</ul>\n<p class=\"fig-p\">```xml</p>\n<p class=\"fig-p\"><xsd:element name=\"AUTOSAR\" type=\"AUTOSAR\"/></p>\n<p class=\"fig-p\">```</p>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf (falls zutreffend)</h4>\n<p class=\"fig-p\">Als statische Metamodell-Regel liegt kein Laufzeitverhalten im Steuergerät vor. Der Ablauf betrifft die <strong>Modellierungs- und Generierungs-Toolchain</strong> (Design- / Build-Time):</p>\n<ol class=\"fig-list\">\n<li><strong>Metamodell-Definition (M2):</strong> Die Metaklasse <code>AUTOSAR</code> wird im UML-Modell mit dem Tag <code>xml.globalElement = true</code> annotiert.</li>\n<li><strong>Schema-Produktion (TPS_XMLSPR_00003):</strong> Der XML-Schema-Generator scannt alle M2-Klassen. Findet er <code>xml.globalElement = true</code>, erzeugt er ein globales <code>xsd:element</code> auf oberster Ebene des XSD-Dokuments (anstelle lediglich eines lokalen Elements oder reinen <code>complexType</code>).</li>\n<li><strong>Typ-Referenzierung (TPS_XMLSPR_00005):</strong> Der Name des generierten XML-Elements entspricht dem Klassennamen (<code>AUTOSAR</code>), und das Attribut <code>type</code> referenziert den korrespondierenden <code>xsd:complexType</code> der Klasse.</li>\n<li><strong>ARXML-Instanziierung (M1):</strong> XML-Parser und Validatoren nutzen das erzeugte globale Schema-Element als zwingend vorgeschriebenen Document-Root für jede AUTOSAR-Austauschdatei (<code>&lt;AUTOSAR xmlns=\"http://autosar.org/schema/r4.0\" ...&gt;</code>).</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>ARXML-Serialisierung & Root-Element:</strong> Jede gültige AUTOSAR-XML-Datei (Classic oder Adaptive Platform) erfordert <code>&lt;AUTOSAR&gt;</code> als Wurzelelement. Ohne diese Produktionsregel würde die W3C-Schema-Validierung scheitern, da Schemata ohne globale Elementdeklaration keine gültigen XML-Dokument-Instanzen erlauben.</li>\n<li><strong>Validierungs- und Toolchain-Auswirkungen:</strong></li>\n<li>Autoren von Generatoren und Modell-Transformationswerkzeugen müssen beachten, dass Sub-Elemente (z. B. einzelne <code>AR-PACKAGE</code>s oder BSW-Modulbeschreibungen) nicht isoliert als Document-Root serialisiert werden dürfen, sofern sie nicht ebenfalls explizit mit <code>xml.globalElement = true</code> versehen sind.</li>\n<li>Beim Aufbau modularer ARXML-Splits verbleibt <code>&lt;AUTOSAR&gt;</code> stets die umschließende Hülle, selbst wenn die Datei nur ein partielles Fragment (z. B. ein einzelnes BswModuleDescription-Package) transportiert.</li>\n</ul>"}, {"id": "FIG-0341c2368e42a947", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt (M2-Ebene) mit Tagged-Value-Spezifikation.</li>\n<li><strong>Funktionale Einordnung & Zweck:</strong></li>\n<li>Das Diagramm stammt aus der AUTOSAR-Foundation-Spezifikation <em>TPS XML Schema Production Rules</em> (<code>AUTOSAR_FO_TPS_XMLSchemaProductionRules</code>, Kapitel 4 „Mapping of Classes“).</li>\n<li>Es demonstriert die normative Vorschrift zur Transformation von Metamodell-Klassen in W3C-XML-Schema-Definitionen (<code>.xsd</code>).</li>\n<li>Standardmäßig werden AUTOSAR-Metaklassen ausschließlich auf <code>xsd:complexType</code> abgebildet. Um ein Wurzelelement für ARXML-Dateien im XSD-Schema global instanziierbar zu machen, dient die UML-Tag-Spezifikation <code>xml.globalElement = true</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Entitäten & Metaklassen:</strong></li>\n<li><code>AUTOSAR</code>: Zentrale Metaklasse an der Spitze der AUTOSAR-Modellhierarchie (Container für <code>ARPackage</code>-Strukturen).</li>\n<li><strong>Stereotypen & Tags (Tagged Values):</strong></li>\n<li>Fachbereich/Compartment: <code>tags</code></li>\n<li><code>xml.globalElement = true</code>: Schalter-Tag für den XSD-Generator gemäß <code>TPS_XMLSPR_00003</code> und <code>TPS_XMLSPR_00005</code>.</li>\n<li><strong>Beziehungen & Kardinalitäten:</strong></li>\n<li>Im Diagramm isoliert als normatives Definitionsmuster dargestellt.</li>\n<li>Im vollständigen Metamodell aggregiert die Metaklasse <code>AUTOSAR</code> die Elemente vom Typ <code>ARPackage</code> (<code>0..*</code>).</li>\n<li>Durch das gesetzte Tag wird die Klasse im Ziel-Schema zu einem globalen Element deklariert:</li>\n</ul>\n<p class=\"fig-p\">```xml</p>\n<p class=\"fig-p\"><xsd:element name=\"AUTOSAR\" type=\"AUTOSAR\"/></p>\n<p class=\"fig-p\">```</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statische Metamodell-Regel liegt kein Laufzeitverhalten im Steuergerät vor. Der Ablauf betrifft die <strong>Modellierungs- und Generierungs-Toolchain</strong> (Design- / Build-Time):</p>\n<ol class=\"fig-list\">\n<li><strong>Metamodell-Definition (M2):</strong> Die Metaklasse <code>AUTOSAR</code> wird im UML-Modell mit dem Tag <code>xml.globalElement = true</code> annotiert.</li>\n<li><strong>Schema-Produktion (TPS_XMLSPR_00003):</strong> Der XML-Schema-Generator scannt alle M2-Klassen. Findet er <code>xml.globalElement = true</code>, erzeugt er ein globales <code>xsd:element</code> auf oberster Ebene des XSD-Dokuments (anstelle lediglich eines lokalen Elements oder reinen <code>complexType</code>).</li>\n<li><strong>Typ-Referenzierung (TPS_XMLSPR_00005):</strong> Der Name des generierten XML-Elements entspricht dem Klassennamen (<code>AUTOSAR</code>), und das Attribut <code>type</code> referenziert den korrespondierenden <code>xsd:complexType</code> der Klasse.</li>\n<li><strong>ARXML-Instanziierung (M1):</strong> XML-Parser und Validatoren nutzen das erzeugte globale Schema-Element als zwingend vorgeschriebenen Document-Root für jede AUTOSAR-Austauschdatei (<code>&lt;AUTOSAR xmlns=\"http://autosar.org/schema/r4.0\" ...&gt;</code>).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>ARXML-Serialisierung & Root-Element:</strong> Jede gültige AUTOSAR-XML-Datei (Classic oder Adaptive Platform) erfordert <code>&lt;AUTOSAR&gt;</code> als Wurzelelement. Ohne diese Produktionsregel würde die W3C-Schema-Validierung scheitern, da Schemata ohne globale Elementdeklaration keine gültigen XML-Dokument-Instanzen erlauben.</li>\n<li><strong>Validierungs- und Toolchain-Auswirkungen:</strong></li>\n<li>Autoren von Generatoren und Modell-Transformationswerkzeugen müssen beachten, dass Sub-Elemente (z. B. einzelne <code>AR-PACKAGE</code>s oder BSW-Modulbeschreibungen) nicht isoliert als Document-Root serialisiert werden dürfen, sofern sie nicht ebenfalls explizit mit <code>xml.globalElement = true</code> versehen sind.</li>\n<li>Beim Aufbau modularer ARXML-Splits verbleibt <code>&lt;AUTOSAR&gt;</code> stets die umschließende Hülle, selbst wenn die Datei nur ein partielles Fragment (z. B. ein einzelnes BswModuleDescription-Package) transportiert.</li>\n</ul>"}], "trans": [{"from": "FIG-99edd6fb5bc44f1d", "to": "FIG-0341c2368e42a947", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-0341c2368e42a947", "to": "FIG-99edd6fb5bc44f1d", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
